local QuarryMiner = {}
local PRODUCTS = {
    limestone_block = { name = "Apnenčev blok", limestoneCost = 1, time = 2, cost = 15, quality = 30, description = "Apnenčev blok iz kamnoloma." },
    sandstone_block = { name = "Peščenjak blok", sandstoneCost = 1, time = 3, cost = 35, quality = 50, prestige = 1, description = "Peščenjak blok za gradnjo." },
    granite_block = { name = "Granitni blok", graniteCost = 1, time = 4, cost = 80, quality = 65, prestige = 3, happiness = 1, description = "Granitni blok za utrdbe." },
    marble_block = { name = "Marmornat blok", marbleCost = 1, time = 6, cost = 200, quality = 80, prestige = 7, happiness = 2, description = "Marmornat blok za fine stavbe." },
    silver_veined_marble = { name = "Srebrno žilnati marmor", marbleCost = 1, silverCost = 1, time = 9, cost = 480, quality = 92, prestige = 14, happiness = 3, description = "Marmor s srebrnimi žilami za plemiče." },
    royal_grand_marble = { name = "Kraljevski veliki marmor", marbleCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 14, cost = 1600, quality = 100, prestige = 36, happiness = 8, description = "Veliki kraljevski marmor z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Kamnoseka postaja", cost = { gold = 250, wood = 100, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    quarry = { name = "Kamnolom", cost = { gold = 900, wood = 200, stone = 400, iron = 8 }, upkeep = 22, qualityBonus = 18 },
    dressing_yard = { name = "Obdelovalnica", cost = { gold = 2200, wood = 300, stone = 600, silver = 25, steel = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_quarry_atelier = { name = "Kraljevski atelje kamna", cost = { gold = 9000, wood = 500, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
QuarryMiner.limestoneStock = 18; QuarryMiner.sandstoneStock = 14; QuarryMiner.graniteStock = 12; QuarryMiner.marbleStock = 10; QuarryMiner.silverStock = 8; QuarryMiner.goldStock = 6; QuarryMiner.jewelStock = 6
QuarryMiner.productStock = {}; QuarryMiner.buildings = {}; QuarryMiner.maker = nil; QuarryMiner.activeMaking = {}; QuarryMiner.totalProducts = 0; QuarryMiner.dayTimer = 0
function QuarryMiner.init() QuarryMiner.limestoneStock=18; QuarryMiner.sandstoneStock=14; QuarryMiner.graniteStock=12; QuarryMiner.marbleStock=10; QuarryMiner.silverStock=8; QuarryMiner.goldStock=6; QuarryMiner.jewelStock=6; QuarryMiner.productStock={}; QuarryMiner.buildings={}; QuarryMiner.maker=nil; QuarryMiner.activeMaking={}; QuarryMiner.totalProducts=0; QuarryMiner.dayTimer=0; print("[QuarryMiner] Royal Quarry Miner System initialized (6 products, 4 buildings)") end
function QuarryMiner.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuarryMiner.maker={name=n or ("Kamnosek "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kamnosek najet: %s (spretnost: %d)",QuarryMiner.maker.name,s),"success") end; return true end
function QuarryMiner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuarryMiner.build(id) local ok,e=QuarryMiner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuarryMiner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuarryMiner.getQualityBonus() local b=0; for _,bd in ipairs(QuarryMiner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuarryMiner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.limestoneCost and QuarryMiner.limestoneStock<(d.limestoneCost or 0) then return false,"Premalo apnenca" end; if d.sandstoneCost and QuarryMiner.sandstoneStock<(d.sandstoneCost or 0) then return false,"Premalo peščenjaka" end; if d.graniteCost and QuarryMiner.graniteStock<(d.graniteCost or 0) then return false,"Premalo granita" end; if d.marbleCost and QuarryMiner.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and QuarryMiner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuarryMiner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuarryMiner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #QuarryMiner.buildings==0 then return false,"Potrebna delavnica" end; if not QuarryMiner.maker then return false,"Potreben kamnosek" end; return true end
function QuarryMiner.make(pt,qty) qty=qty or 5; local ok,e=QuarryMiner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.limestoneCost then QuarryMiner.limestoneStock=QuarryMiner.limestoneStock-d.limestoneCost*qty end; if d.sandstoneCost then QuarryMiner.sandstoneStock=QuarryMiner.sandstoneStock-d.sandstoneCost*qty end; if d.graniteCost then QuarryMiner.graniteStock=QuarryMiner.graniteStock-d.graniteCost*qty end; if d.marbleCost then QuarryMiner.marbleStock=QuarryMiner.marbleStock-d.marbleCost*qty end; if d.silverCost then QuarryMiner.silverStock=QuarryMiner.silverStock-d.silverCost*qty end; if d.goldCost then QuarryMiner.goldStock=QuarryMiner.goldStock-d.goldCost*qty end; if d.jewelCost then QuarryMiner.jewelStock=QuarryMiner.jewelStock-d.jewelCost*qty end; local t=d.time; if QuarryMiner.maker then t=math.max(1,t-math.floor(QuarryMiner.maker.skill/12)) end; table.insert(QuarryMiner.activeMaking,{id="quarry_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuarryMiner.completeMaking(m) local q=1.0+(QuarryMiner.getQualityBonus()/100); if QuarryMiner.maker then q=q+(QuarryMiner.maker.skill/180) end; q=math.min(2.0,q); QuarryMiner.productStock[m.productType]=(QuarryMiner.productStock[m.productType] or 0)+m.quantity; QuarryMiner.totalProducts=QuarryMiner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuarryMiner.maker then QuarryMiner.maker.itemsMade=QuarryMiner.maker.itemsMade+m.quantity; if math.random()<0.20 then QuarryMiner.maker.skill=math.min(100,QuarryMiner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kamen izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quarry.completed",{productName=m.productName,quality=m.quality}) end end
function QuarryMiner.update(dt) if not _G.state then return end; QuarryMiner.dayTimer=QuarryMiner.dayTimer+dt; if QuarryMiner.dayTimer>=30 then QuarryMiner.dayTimer=0; for i=#QuarryMiner.activeMaking,1,-1 do local m=QuarryMiner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuarryMiner.completeMaking(m); table.remove(QuarryMiner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuarryMiner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuarryMiner.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuarryMiner.getStats() return {limestoneStock=QuarryMiner.limestoneStock,sandstoneStock=QuarryMiner.sandstoneStock,graniteStock=QuarryMiner.graniteStock,marbleStock=QuarryMiner.marbleStock,silverStock=QuarryMiner.silverStock,goldStock=QuarryMiner.goldStock,jewelStock=QuarryMiner.jewelStock,productStock=QuarryMiner.productStock,numBuildings=#QuarryMiner.buildings,hasMaker=QuarryMiner.maker~=nil,makerName=QuarryMiner.maker and QuarryMiner.maker.name or "—",makerSkill=QuarryMiner.maker and QuarryMiner.maker.skill or 0,activeMaking=#QuarryMiner.activeMaking,totalProducts=QuarryMiner.totalProducts} end
return QuarryMiner
